previewCss:
.darma-loader-washing-machine {
  position: relative;
  width: 48px;
  height: 48px;
  border: 3px solid var(--loader-color, #6366f1);
  border-radius: 8px;
  box-sizing: border-box;
}
.darma-loader-washing-machine::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 34px;
  height: 34px;
  margin: -17px 0 0 -17px;
  border-radius: 50%;
  border: 3px solid #c7d2fe;
  box-sizing: border-box;
}
.darma-loader-washing-machine i {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 32px;
  height: 32px;
  margin: -16px 0 0 -16px;
  border-radius: 50%;
  animation: darma-loader-washing-machine-spin 0.9s linear infinite;
}
.darma-loader-washing-machine i::before {
  content: "";
  position: absolute;
  top: 2px;
  left: 50%;
  width: 8px;
  height: 8px;
  margin-left: -4px;
  border-radius: 50%;
  background: var(--loader-color, #6366f1);
}
@keyframes darma-loader-washing-machine-spin { to { transform: rotate(360deg); } }

